D=Path(__file__).resolve().parents[1];P=D.parent/'WeldStressAI_ManuscriptRevision_R2';source=pd.read_csv(D/'REGIONAL_ERROR_SOURCE.csv');plate=pd.read_csv(D/'REGIONAL_ERROR_PLATE.csv')
